def _compact_match_text(*parts: Any) -> str:
    return re.sub(r"\s+", "", " ".join(str(p or "") for p in parts)).lower()


def _infer_task_capabilities(message: str, file_assets: list[FileAsset] | None = None, *, participant_count: int = 1) -> list[dict[str, Any]]:
    compact = _compact_match_text(message)
    required: list[dict[str, Any]] = []
    seen: set[str] = set()
    for rule in CAPABILITY_RULES:
        patterns = [str(p).lower() for p in rule.get("patterns", [])]
        if any(_compact_match_text(p) in compact for p in patterns):
            item = {
                "key": rule["key"],
                "label": rule["label"],
                "type": rule.get("type", "skill"),
                "reason": "任务描述命中能力需求",
                "required": True,
            }
            required.append(item)
            seen.add(rule["key"])
    if file_assets and "file_context" not in seen:
        required.append({
            "key": "file_context",
            "label": "文件上下文",
            "type": "context",
            "reason": f"本轮上传/选择了 {len(file_assets)} 个附件",
            "required": True,
        })
        seen.add("file_context")
    if participant_count > 1 and "multi_agent" not in seen:
        required.append({
            "key": "multi_agent",
            "label": "多员工协作",
            "type": "workflow",
            "reason": f"本轮包含 {participant_count} 位员工",
            "required": True,
        })
    return required


def _employee_skill_packages(db: Session, employee_id: str | None) -> list[SkillPackage]:
    if not employee_id:
        return []
    rows = db.execute(
        select(SkillPackage)
        .join(SkillBinding, SkillPackage.id == SkillBinding.skill_id)
        .where(
            SkillBinding.target_type == "employee",
            SkillBinding.target_id == employee_id,
            SkillBinding.enabled == True,  # noqa: E712
            SkillPackage.status == "enabled",
        )
    ).scalars().all()
    return list(rows)


def _employee_capability_profile(db: Session, emp: DigitalEmployee | None) -> dict[str, Any]:
    if not emp:
        return {"keys": [], "labels": [], "toolsets": [], "skills": [], "unrestricted_tools": False}
    toolsets = _employee_allowed_toolsets(emp)
    skills = _employee_skill_packages(db, emp.id)
    skill_text = " ".join(f"{s.name} {s.slug} {s.description} {s.category} {s.source_ref or ''}" for s in skills)
    profile_text = _compact_match_text(emp.display_name, emp.description, emp.system_prompt, emp.toolsets, skill_text)
    keys: set[str] = set()
    for rule in CAPABILITY_RULES:
        aliases = [str(a).lower() for a in rule.get("aliases", [])]
        if rule.get("toolsets") and (set(rule["toolsets"]) & toolsets):
            keys.add(rule["key"])
        elif any(_compact_match_text(alias) in profile_text for alias in aliases):
            keys.add(rule["key"])
    if "stock_data" in keys:
        keys.update({"web_search", "report_generation"})
    if "document_processing" in keys:
        keys.update({"file_context", "report_generation"})
    if "spreadsheet" in keys:
        keys.update({"file_context", "code_execution", "report_generation"})
    if "terminal" in toolsets:
        keys.add("code_execution")
    labels = [str(rule["label"]) for rule in CAPABILITY_RULES if rule["key"] in keys]
    return {
        "employee_id": emp.id,
        "employee_name": emp.display_name,
        "keys": sorted(keys),
        "labels": labels,
        "toolsets": sorted(toolsets),
        "skills": [
            {
                "id": s.id,
                "name": s.name,
                "slug": s.slug,
                "category": s.category,
                "source_ref": s.source_ref,
            }
            for s in skills[:12]
        ],
        "unrestricted_tools": not bool(toolsets),
    }


def _capability_available(profile: dict[str, Any], capability_key: str) -> bool:
    if capability_key in set(profile.get("keys") or []):
        return True
    # Empty toolsets means OpenAtlas is not blocking runtime tools for this
    # employee. Treat tool-level capabilities as available but mark them as
    # implicitly governed in the visible plan.
    if profile.get("unrestricted_tools"):
        rule = next((r for r in CAPABILITY_RULES if r["key"] == capability_key), None)
        return bool(rule and rule.get("type") in {"tool", "context", "output"})
    return False


def _employee_capability_score(profile: dict[str, Any], required: list[dict[str, Any]]) -> int:
    return sum(1 for cap in required if _capability_available(profile, str(cap.get("key") or "")))


def _build_capability_plan(
    db: Session,
    p: Principal,
    *,
    message: str,
    file_assets: list[FileAsset],
    employees: list[DigitalEmployee],
) -> dict[str, Any]:
    required = _infer_task_capabilities(message, file_assets, participant_count=max(1, len(employees)))
    profiles = [_employee_capability_profile(db, emp) for emp in employees]
    current_profile = profiles[0] if profiles else {}
    gaps = [
        {
            **cap,
            "status": "missing",
            "reason": f"当前员工缺少 {cap.get('label')}",
        }
        for cap in required
        if not _capability_available(current_profile, str(cap.get("key") or ""))
    ]
    visible_candidates = [
        emp for emp in db.query(DigitalEmployee).filter(
            DigitalEmployee.tenant_id == p.tenant.id,
            DigitalEmployee.status == EmployeeStatus.active,
        ).all()
        if _employee_visible_to_principal(db, emp, p)
    ]
    suggestions = []
    for emp in visible_candidates:
        profile = _employee_capability_profile(db, emp)
        score = _employee_capability_score(profile, required)
        if score <= 0:
            continue
        suggestions.append({
            "employee_id": emp.id,
            "employee_name": emp.display_name,
            "score": score,
            "matched": [
                cap for cap in required
                if _capability_available(profile, str(cap.get("key") or ""))
            ],
            "profile": {
                "keys": profile.get("keys") or [],
                "labels": profile.get("labels") or [],
                "toolsets": profile.get("toolsets") or [],
                "skills": profile.get("skills") or [],
            },
        })
    suggestions.sort(key=lambda item: (-int(item["score"]), item["employee_name"]))
    current_score = _employee_capability_score(current_profile, required)
    best = suggestions[0] if suggestions else None
    auto_route = None
    if employees and len(employees) == 1 and best and best["employee_id"] != employees[0].id:
        best_score = int(best["score"])
        if gaps and best_score > current_score and best_score >= max(1, len(required) - 1):
            auto_route = best
    return {
        "required_capabilities": required,
        "current_employee": current_profile,
        "employee_profiles": profiles,
        "gaps": gaps,
        "suggested_employees": suggestions[:5],
        "auto_route": auto_route,
        "summary": _capability_plan_summary(required, gaps, auto_route),
    }


def _capability_plan_summary(required: list[dict[str, Any]], gaps: list[dict[str, Any]], auto_route: dict[str, Any] | None) -> str:
    if not required:
        return "未识别到额外能力需求，按当前员工默认能力执行。"
    labels = "、".join(str(item.get("label") or item.get("key")) for item in required)
    if auto_route:
        return f"本任务需要 {labels}；已路由给更匹配的「{auto_route.get('employee_name')}」。"
    if gaps:
        missing = "、".join(str(item.get("label") or item.get("key")) for item in gaps)
        return f"本任务需要 {labels}；当前员工缺少 {missing}，将使用可用上下文并提示授权/转交。"
    return f"本任务需要 {labels}；当前员工能力满足。"


def _build_collaboration_policy(message: str, employees: list[DigitalEmployee], capability_plan: dict[str, Any]) -> dict[str, Any]:
    if len(employees) <= 1:
        return {
            "mode": "single",
            "requires_synthesis": False,
            "owner_employee_id": employees[0].id if employees else None,
            "owner_name": employees[0].display_name if employees else "",
            "steps": ["任务理解", "执行", "最终交付"],
        }
    compact = _compact_match_text(message)
    serial_markers = ("接力", "先", "然后", "再由", "最后由", "审校", "复核", "修改", "润色")
    parallel_markers = ("合作", "一起", "协作", "分工", "合稿", "整合", "推广计划", "方案", "报告")
    serial = any(marker in compact for marker in serial_markers)
    parallel = any(marker in compact for marker in parallel_markers)
    requires_synthesis = parallel or not serial
    owner = employees[0]
    return {
        "mode": "parallel_synthesis" if requires_synthesis else "serial_handoff",
        "requires_synthesis": requires_synthesis,
        "owner_employee_id": owner.id,
        "owner_name": owner.display_name,
        "steps": (
            ["任务理解", "分工规划", "员工执行", "合稿整合", "审校补全", "最终交付"]
            if requires_synthesis else
            ["任务理解", "接力执行", "末棒整合", "最终交付"]
        ),
        "participant_count": len(employees),
        "capability_summary": capability_plan.get("summary") or "",
    }


def _select_synthesizer_employee(
    db: Session,
    p: Principal,
    employees: list[DigitalEmployee],
) -> DigitalEmployee | None:
    preferred_terms = ("项目交付经理", "高管简报秘书", "产品需求经理", "行政小六")
    visible = [
        emp for emp in db.query(DigitalEmployee).filter(
            DigitalEmployee.tenant_id == p.tenant.id,
            DigitalEmployee.status == EmployeeStatus.active,
        ).all()
        if _employee_visible_to_principal(db, emp, p)
    ]
    for term in preferred_terms:
        match = next((emp for emp in visible if term in emp.display_name), None)
        if match:
            return match
    return employees[0] if employees else None


def _capability_prompt_block(plan: dict[str, Any], policy: dict[str, Any]) -> str:
    required = plan.get("required_capabilities") or []
    gaps = plan.get("gaps") or []
    suggestions = plan.get("suggested_employees") or []
    return (
        "<openatlas_capability_dispatch>\n"
        "Atlas has already analyzed this task before execution. Do not tell the user you simply cannot perform the task if a routed employee, bound Skill, file context, or fallback delivery path is available.\n"
        f"Capability summary: {plan.get('summary') or ''}\n"
        f"Required capabilities: {', '.join(str(x.get('label') or x.get('key')) for x in required) or 'none'}\n"
        f"Current gaps: {', '.join(str(x.get('label') or x.get('key')) for x in gaps) or 'none'}\n"
        f"Suggested employees: {', '.join(str(x.get('employee_name')) for x in suggestions[:3]) or 'none'}\n"
        f"Collaboration policy: {policy.get('mode')} / steps: {' -> '.join(policy.get('steps') or [])}\n"
        "If a required capability is missing, clearly state the missing authorization or suggest transfer, but still provide the best reviewable result from available context.\n"
        "</openatlas_capability_dispatch>"
    )


def _is_stale_running_session(row: SessionRecord) -> bool:
    if (getattr(row, "task_status", "") or "") != "running" or not row.updated_at:
        return False
    updated_at = row.updated_at
    if updated_at.tzinfo is None:
        updated_at = updated_at.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - updated_at).total_seconds() > 30 * 60


def _session_health_snapshot(db: Session, rec: SessionRecord) -> dict:
    rows = db.query(MessageRecord).filter_by(session_id=rec.id).order_by(MessageRecord.created_at.asc()).all()
    artifacts = db.query(TaskArtifact).filter(
        TaskArtifact.session_id == rec.id,
        TaskArtifact.tenant_id == rec.tenant_id,
        TaskArtifact.archived == False,  # noqa: E712
    ).all()
    contexts = db.query(ContextInjection).filter(
        ContextInjection.session_id == rec.id,
        ContextInjection.tenant_id == rec.tenant_id,
    ).all()
    canvas_events = db.query(CanvasEvent).filter(
        CanvasEvent.session_id == rec.id,
        CanvasEvent.tenant_id == rec.tenant_id,
    ).order_by(CanvasEvent.created_at.desc()).limit(20).all()
    latest_user = next((r for r in reversed(rows) if r.role == "user"), None)
    latest_assistant_after_user = None
    if latest_user:
        latest_assistant_after_user = next(
            (
                r for r in reversed(rows)
                if r.role == "assistant" and r.created_at >= latest_user.created_at
            ),
            None,
        )
    pending_runs = [
        {"run_id": rid, **meta}
        for rid, meta in _PENDING_HERMES_RUNS.items()
        if meta.get("session_id") == rec.id
    ]
    issues: list[dict[str, Any]] = []
    actions: list[dict[str, Any]] = []
    status = rec.task_status or "draft"
    if status == "failed":
        issues.append({"code": "task_failed", "severity": "critical", "message": "任务已标记失败，需要重新执行或人工处理。"})
        actions.append({"key": "retry", "label": "重新进行", "kind": "task_status", "value": "running"})
    if status == "needs_input":
        issues.append({"code": "needs_input", "severity": "warning", "message": rec.task_summary or "任务需要用户补充信息。"})
        actions.append({"key": "resume", "label": "继续补充", "kind": "resume"})
    if status == "quota_waiting":
        issues.append({"code": "quota_waiting", "severity": "warning", "message": rec.task_summary or "模型服务处于限流等待，可稍后继续。"})
        actions.append({"key": "retry", "label": "稍后重试本轮", "kind": "task_status", "value": "running", "primary": True})
        actions.append({"key": "resume", "label": "换员工接力", "kind": "resume"})
    if _is_stale_running_session(rec):
        issues.append({"code": "stale_running", "severity": "critical", "message": "任务运行中但超过 30 分钟没有更新。"})
        actions.append({"key": "recover", "label": "同步最新结果", "kind": "recover"})
        actions.append({"key": "inspect_runtime", "label": "检查 Runtime", "kind": "runtime"})
    if latest_user and not latest_assistant_after_user:
        issues.append({"code": "awaiting_assistant", "severity": "warning", "message": "最近一轮用户输入后还没有可见模型回复。"})
        actions.append({"key": "recover", "label": "同步 Hermes 会话", "kind": "recover"})
    if latest_user and not contexts:
        issues.append({"code": "missing_context_trace", "severity": "warning", "message": "本会话缺少上下文注入记录，难以追溯文件、Skill、记忆来源。"})
        actions.append({"key": "retry_with_context", "label": "重新带上下文执行", "kind": "resume"})
    if rows and not artifacts:
        assistant_text = "\n\n".join(r.content or "" for r in rows if r.role == "assistant")
        if _extract_task_artifacts(assistant_text, prefix="health-probe"):
            issues.append({"code": "unregistered_artifact", "severity": "warning", "message": "回复中疑似包含交付物，但没有登记到输出物。"})
            actions.append({"key": "recover", "label": "重新抽取交付物", "kind": "recover"})
    if pending_runs:
        issues.append({"code": "pending_hermes_run", "severity": "info", "message": f"仍有 {len(pending_runs)} 个 Hermes Run 处于可追踪状态。"})
    latest_event = canvas_events[0] if canvas_events else None
    latest_run = db.query(SessionRun).filter(
        SessionRun.session_id == rec.id,
        SessionRun.tenant_id == rec.tenant_id,
    ).order_by(SessionRun.created_at.desc()).first()
    latest_workflow = db.query(WorkflowRun).filter(
        WorkflowRun.session_id == rec.id,
        WorkflowRun.tenant_id == rec.tenant_id,
    ).order_by(WorkflowRun.created_at.desc()).first()
    score = 100
    severity_penalty = {"critical": 28, "warning": 14, "info": 4}
    for issue in issues:
        score -= severity_penalty.get(issue.get("severity"), 8)
    if rows and not contexts:
        score -= 10
    if artifacts and not any((_artifact_provenance(db, a).get("context_counts") or {}) for a in artifacts[:3]):
        score -= 8
    score = max(0, min(100, score))
    health_status = "healthy"
    if any(i.get("severity") == "critical" for i in issues):
        health_status = "action_required"
    elif any(i.get("severity") == "warning" for i in issues):
        health_status = "warning"
    elif status == "running" or pending_runs:
        health_status = "running"
    return {
        "status": health_status,
        "score": score,
        "task_status": status,
        "is_stale": _is_stale_running_session(rec),
        "issues": issues,
        "recommended_actions": actions,
        "pending_runs": [{"run_id": item.get("run_id"), "created_at": item.get("created_at")} for item in pending_runs],
        "counts": {
            "messages": len(rows),
            "user_turns": sum(1 for r in rows if r.role == "user"),
            "assistant_turns": sum(1 for r in rows if r.role == "assistant"),
            "context_injections": len(contexts),
            "artifacts": len(artifacts),
            "canvas_events": db.query(CanvasEvent).filter(CanvasEvent.session_id == rec.id, CanvasEvent.tenant_id == rec.tenant_id).count(),
        },
        "latest_runtime_event": _canvas_event_to_dict(latest_event) if latest_event else None,
        "latest_run": _session_run_to_dict(latest_run) if latest_run else None,
        "latest_workflow": _workflow_run_to_dict(latest_workflow) if latest_workflow else None,
        "progress": _session_progress_snapshot(db, rec, latest_run=latest_run, latest_workflow=latest_workflow),
    }


def _context_to_dict(row: ContextInjection) -> dict:
    try:
        payload = json.loads(row.payload or "{}")
    except Exception:
        payload = {}
    return {
        "id": row.id,
        "session_id": row.session_id,
        "message_id": row.message_id,
        "employee_id": row.employee_id,
        "turn_index": row.turn_index,
        "kind": row.kind,
        "source_id": row.source_id,
        "name": row.name,
        "scope": row.scope,
        "status": row.status,
        "summary": row.summary,
        "payload": payload,
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }


def _artifact_provenance(db: Session, row: TaskArtifact) -> dict:
    msg = db.get(MessageRecord, row.message_id) if row.message_id else None
    run = db.get(SessionRun, row.run_id) if getattr(row, "run_id", None) else None
    extra = _json_loads_obj(getattr(row, "provenance_payload", "") or "{}", {})
    if not isinstance(extra, dict):
        extra = {}
    context_q = db.query(ContextInjection).filter(
        ContextInjection.session_id == row.session_id,
        ContextInjection.tenant_id == row.tenant_id,
    )
    if msg and msg.id:
        context_q = context_q.filter(ContextInjection.message_id == msg.id)
    context_rows = context_q.order_by(ContextInjection.created_at.desc()).limit(40).all()
    context_counts: dict[str, int] = {}
    for c in context_rows:
        context_counts[c.kind] = context_counts.get(c.kind, 0) + 1
    user_q = db.query(MessageRecord).filter(
        MessageRecord.session_id == row.session_id,
        MessageRecord.role == "user",
    )
    if row.created_at:
        user_q = user_q.filter(MessageRecord.created_at <= row.created_at)
    user_msg = user_q.order_by(MessageRecord.created_at.desc()).first()
    raw_source_path = getattr(row, "source_path", "") or ""
    source_name = Path(raw_source_path).name if raw_source_path else ""
    return {
        "source": row.source,
        "source_path": "",
        "source_name": source_name,
        "run_id": getattr(row, "run_id", None),
        "hermes_run_id": run.hermes_run_id if run else "",
        "employee_id": getattr(row, "employee_id", None) or (msg.speaker_employee_id if msg else None),
        "employee_name": msg.speaker_name if msg else "",
        "message_id": row.message_id,
        "turn_index": msg.turn_index if msg else None,
        "query_excerpt": (user_msg.content or "")[:180] if user_msg else "",
        "context_counts": context_counts,
        "context_items": [_context_to_dict(c) for c in context_rows[:12]],
        **extra,
    }


def _artifact_to_dict(row: TaskArtifact, db: Session | None = None) -> dict:
    managed_path = _materialize_artifact_file(db, row) if db is not None else (
        Path(row.storage_path) if getattr(row, "storage_path", "") else None
    )
    raw_source_path = getattr(row, "source_path", "") or ""
    is_binary = _is_binary_artifact_name(row.name or "", row.mime_type) or _content_looks_binary_stub(row.content or "")
    display_kind = row.kind
    if is_binary and display_kind in {"report", "artifact", "file", ""}:
        display_kind = _artifact_kind_for_file(Path(row.name or ""), row.mime_type)
    out = {
        "id": row.id,
        "session_id": row.session_id,
        "message_id": row.message_id,
        "kind": display_kind,
        "name": row.name,
        "mime_type": row.mime_type,
        "content": "" if is_binary else row.content,
        "source": row.source,
        "source_path": "",
        "source_name": Path(raw_source_path).name if raw_source_path else "",
        "storage_ref": f"artifact:{row.id}" if getattr(row, "storage_path", "") else "",
        "storage_size": int(getattr(row, "storage_size", 0) or 0),
        "managed_status": getattr(row, "managed_status", "") or ("managed" if managed_path else "pending"),
        "run_id": getattr(row, "run_id", None),
        "employee_id": getattr(row, "employee_id", None),
        "version": int(getattr(row, "version", 1) or 1),
        "status": row.status,
        "archived": row.archived,
        "created_at": row.created_at.isoformat() if row.created_at else None,
    }
    if db is not None:
        out["provenance"] = _artifact_provenance(db, row)
    return out


def _dedupe_artifact_rows_for_display(rows: list[TaskArtifact]) -> list[TaskArtifact]:
    """Hide duplicate discoveries of the same generated file/content."""
    seen_paths: set[str] = set()
    seen_content: set[tuple[str, str]] = set()
    result: list[TaskArtifact] = []
    for row in rows:
        path = getattr(row, "source_path", "") or ""
        content_key = _artifact_content_key(row.name, row.content or "")
        display_content_key = (row.name, content_key[2]) if content_key else None
        if path and path in seen_paths:
            continue
        if display_content_key and display_content_key in seen_content:
            continue
        result.append(row)
        if path:
            seen_paths.add(path)
        if display_content_key:
            seen_content.add(display_content_key)
    return result


def _can_access_artifact(row: TaskArtifact | None, p: Principal) -> bool:
    if not row or row.tenant_id != p.tenant.id:
        return False
    if p.user.role in (UserRole.tenant_admin, UserRole.system_admin):
        return True
    return row.user_id == p.user.id


def _record_context_injections(
    db: Session,
    *,
    tenant_id: str,
    user_id: str,
    session_id: str,
    message_id: str | None,
    employee_id: str | None,
    turn_index: int | None,
    skills: list[dict],
    memories: list[dict],
    files: list[dict],
) -> list[ContextInjection]:
    rows: list[ContextInjection] = []
    for item in skills:
        row = ContextInjection(
            tenant_id=tenant_id,
            user_id=user_id,
            session_id=session_id,
            message_id=message_id,
            employee_id=employee_id,
            turn_index=turn_index,
            kind="skill",
            source_id=str(item.get("id") or ""),
            name=str(item.get("name") or item.get("slug") or "Skill"),
            scope=str(item.get("scope") or ""),
            status=str(item.get("status") or "injected"),
            summary=str(item.get("summary") or "")[:1200],
            payload=json.dumps(item, ensure_ascii=False),
        )
        db.add(row)
        rows.append(row)
    for item in memories:
        row = ContextInjection(
            tenant_id=tenant_id,
            user_id=user_id,
            session_id=session_id,
            message_id=message_id,
            employee_id=employee_id,
            turn_index=turn_index,
            kind="memory",
            source_id=str(item.get("id") or ""),
            name=str(item.get("title") or "Memory"),
            scope=str(item.get("scope") or ""),
            status="injected",
            summary=str(item.get("content") or "")[:1200],
            payload=json.dumps(item, ensure_ascii=False),
        )
        db.add(row)
        rows.append(row)
    for item in files:
        row = ContextInjection(
            tenant_id=tenant_id,
            user_id=user_id,
            session_id=session_id,
            message_id=message_id,
            employee_id=employee_id,
            turn_index=turn_index,
            kind="file",
            source_id=str(item.get("id") or ""),
            name=str(item.get("name") or item.get("original_name") or "File"),
            scope="session",
            status=str(item.get("status") or "injected"),
            summary=str(item.get("summary") or "")[:1200],
            payload=json.dumps(item, ensure_ascii=False),
        )
        db.add(row)
        rows.append(row)
    return rows


_FENCE_ARTIFACTS = {
    "html": ("html", "text/html;charset=utf-8", "html"),
    "htm": ("html", "text/html;charset=utf-8", "html"),
    "markdown": ("markdown", "text/markdown;charset=utf-8", "md"),
    "md": ("markdown", "text/markdown;charset=utf-8", "md"),
    "mermaid": ("mermaid", "text/plain;charset=utf-8", "mmd"),
    "json": ("json", "application/json;charset=utf-8", "json"),
    "csv": ("table", "text/csv;charset=utf-8", "csv"),
}


def _extract_task_artifacts(text: str, *, prefix: str = "交付物") -> list[dict]:
    artifacts: list[dict] = []
    seen_spans: list[tuple[int, int]] = []
    fence_re = re.compile(r"```([a-zA-Z0-9_+\-]*)[ \t]*\n?([\s\S]*?)```")
    for idx, m in enumerate(fence_re.finditer(text), start=1):
        lang = (m.group(1) or "").lower()
        if lang not in _FENCE_ARTIFACTS:
            continue
        kind, mime, ext = _FENCE_ARTIFACTS[lang]
        content = (m.group(2) or "").strip()
        if not content:
            continue
        seen_spans.append((m.start(), m.end()))
        if kind == "html":
            content = _wrap_html_artifact(content)
        artifacts.append({
            "kind": kind,
            "name": f"{prefix}-{idx}.{ext}",
            "mime_type": mime,
            "content": content,
        })
    stripped = text.strip()
    if not any(a["kind"] == "html" for a in artifacts):
        html = _extract_standalone_html(stripped)
        if html:
            artifacts.append({
                "kind": "html",
                "name": f"{prefix}-页面.html",
                "mime_type": "text/html;charset=utf-8",
                "content": _wrap_html_artifact(html),
            })
    return artifacts[:12]


def _extract_standalone_html(text: str) -> str:
    if not text:
        return ""
    if re.match(r"^\s*(<!doctype html|<html[\s>])", text, flags=re.I):
        return text
    m = re.search(r"(<(?:section|article|main|div|html|body|table|style|script)[\s\S]*?</(?:section|article|main|div|html|body|table|style|script)>)", text, flags=re.I)
    return m.group(1).strip() if m else ""


def _wrap_html_artifact(html: str) -> str:
    if re.match(r"^\s*(<!doctype|<html)", html, flags=re.I):
        return html
    return f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>OpenAtlas Artifact</title>
</head>
<body>
{html}
</body>
</html>"""


def _tenant_dashboard_metrics(db: Session, tid: str, *, user_id: str | None = None) -> dict:
    msg_q = db.query(MessageRecord).join(SessionRecord, MessageRecord.session_id == SessionRecord.id).filter(
        SessionRecord.tenant_id == tid,
    )
    sess_q = db.query(SessionRecord).filter(SessionRecord.tenant_id == tid)
    file_q = db.query(FileAsset).filter(FileAsset.tenant_id == tid)
    audit_q = db.query(AuditLog).filter(AuditLog.tenant_id == tid)
    artifact_q = db.query(TaskArtifact).filter(TaskArtifact.tenant_id == tid)
    skill_run_q = db.query(SkillRun).filter(SkillRun.tenant_id == tid)
    if user_id:
        msg_q = msg_q.filter(SessionRecord.user_id == user_id)
        sess_q = sess_q.filter(SessionRecord.user_id == user_id)
        file_q = file_q.filter(FileAsset.user_id == user_id)
        audit_q = audit_q.filter(AuditLog.user_id == user_id)
        artifact_q = artifact_q.filter(TaskArtifact.user_id == user_id)
        skill_run_q = skill_run_q.filter(SkillRun.user_id == user_id)
    messages = msg_q.all()
    files = file_q.all()
    audits = audit_q.all()
    sessions = sess_q.all()
    skill_runs_all = skill_run_q.order_by(SkillRun.created_at.desc()).all()
    skill_window = int(os.environ.get("OPENATLAS_DASHBOARD_SKILL_RUN_WINDOW", "100"))
    skill_runs = skill_runs_all[:max(1, skill_window)]
    artifacts = artifact_q.all()
    input_tokens = sum(int(m.input_tokens or 0) for m in messages)
    output_tokens = sum(int(m.output_tokens or 0) for m in messages)
    failed = sum(1 for a in audits if any(k in (a.action or "").lower() for k in ("error", "failed", "fail")))
    task_status_counts: dict[str, int] = {}
    for s in sessions:
        status = getattr(s, "task_status", "draft") or "draft"
        task_status_counts[status] = task_status_counts.get(status, 0) + 1
    skill_fail = sum(1 for r in skill_runs if r.status in ("failed", "missing_in_hermes", "read_failed", "skipped_budget"))
    return {
        "active_users": db.query(User).filter(User.tenant_id == tid, User.is_active == True).count(),  # noqa: E712
        "messages": len(messages),
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "total_tokens": input_tokens + output_tokens,
        "input_chars": sum(len(m.content or "") for m in messages if m.role == "user"),
        "output_chars": sum(len(m.content or "") for m in messages if m.role == "assistant"),
        "files": len(files),
        "file_bytes": sum(int(f.size or 0) for f in files),
        "expired_files": sum(1 for f in files if _file_to_dict(f)["is_expired"]),
        "artifacts": len(artifacts),
        "artifact_kinds": {k: sum(1 for a in artifacts if a.kind == k) for k in sorted({a.kind for a in artifacts})},
        "skill_runs": len(skill_runs),
        "skill_runs_total": len(skill_runs_all),
        "skill_run_window": max(1, skill_window),
        "skill_failures": skill_fail,
        "skill_failure_rate": round(skill_fail / max(1, len(skill_runs)), 4),
        "audit_events": len(audits),
        "failure_events": failed,
        "failure_rate": round(failed / max(1, len(audits)), 4),
        "sessions": len(sessions),
        "task_status_counts": task_status_counts,
    }


def _template_to_dict(t: CollaborationTemplate) -> dict:
    try:
        participant_ids = json.loads(t.participant_ids or "[]")
    except Exception:
        participant_ids = []
    canvas_state = None
    if t.canvas_state:
        try:
            canvas_state = json.loads(t.canvas_state)
        except Exception:
            canvas_state = None
    plan_nodes: list[dict] = []
    plan_edges: list[dict] = []
    if canvas_state:
        raw_nodes = canvas_state.get("nodes") if isinstance(canvas_state, dict) else []
        raw_edges = canvas_state.get("edges") if isinstance(canvas_state, dict) else []
        for idx, node in enumerate(raw_nodes or []):
            if not isinstance(node, dict):
                continue
            data = node.get("data") if isinstance(node.get("data"), dict) else {}
            role = data.get("role") or ("user" if node.get("id") == "user" else "employee")
            plan_nodes.append({
                "node_id": node.get("id"),
                "order": idx,
                "role": role,
                "employee_id": data.get("employeeId") or data.get("employee_id"),
                "name": data.get("label") or data.get("name"),
                "default_prompt": data.get("prompt") or "",
                "output_type": data.get("outputType") or data.get("output_type") or "markdown",
                "skills": data.get("skills") if isinstance(data.get("skills"), list) else [],
            })
        for edge in raw_edges or []:
            if isinstance(edge, dict):
                plan_edges.append({
                    "source": edge.get("source"),
                    "target": edge.get("target"),
                    "mode": edge.get("mode") or "relay",
                })
    relay_count = max(0, len(participant_ids))
    meta = canvas_state.get("meta") if isinstance(canvas_state, dict) and isinstance(canvas_state.get("meta"), dict) else {}
    collaboration_plan = {
        "strategy": meta.get("strategy") or ("relay" if relay_count else "single"),
        "failure_strategy": meta.get("failure_strategy") or "continue_with_next_employee",
        "primary_employee_id": t.primary_employee_id,
        "participant_ids": participant_ids,
        "nodes": plan_nodes,
        "edges": plan_edges,
        "output_types": sorted({n.get("output_type") or "markdown" for n in plan_nodes if n.get("role") == "employee"}) or ["markdown"],
        "default_prompt": meta.get("default_prompt") or "",
        "relay_count": relay_count,
    }
    return {
        "id": t.id,
        "name": t.name,
        "description": t.description,
        "category": getattr(t, "category", "general") or "general",
        "visibility": getattr(t, "visibility", "private") or "private",
        "primary_employee_id": t.primary_employee_id,
        "participant_ids": participant_ids,
        "canvas_state": canvas_state,
        "collaboration_plan": collaboration_plan,
        "source_session_id": t.source_session_id,
        "created_at": t.created_at.isoformat() if t.created_at else None,
        "updated_at": t.updated_at.isoformat() if t.updated_at else None,
    }


