    {"key": "workbench.use", "label": "工作台使用", "group": "基础"},
    {"key": "employee.view", "label": "查看数智员工", "group": "基础"},
    {"key": "employee.create", "label": "招聘新员工", "group": "基础"},
    {"key": "skill.center.view", "label": "技能中心", "group": "基础"},
